#!/usr/bin/env python3
"""Reproduce the applied practice calculations for M01."""

from math import exp, isclose, log

# B: explicitly simulated inputs, generated by the stated fixed pattern.
# T = exp(-alpha * L * c), with p0 = 1 atm and c in nmol/mol / 1e9.
alpha_old = 308.32  # atm^-1 cm^-1
alpha_new = 304.39  # atm^-1 cm^-1
path_cm = 90.0
standard_pressure_atm = 1.0
concentrations_target = (100.0, 250.0, 500.0)
transmittances = tuple(
    exp(-alpha_old * path_cm * (c / 1e9) * standard_pressure_atm)
    for c in concentrations_target
)

def srp_output(T, alpha):
    return -log(T) / (alpha * path_cm) / standard_pressure_atm * 1e9

b_results = []
for target, T in zip(concentrations_target, transmittances):
    old = srp_output(T, alpha_old)
    new = srp_output(T, alpha_new)
    difference = new - old
    relative = difference / old
    b_results.append((old, new, difference, relative))
    print(f"B target={target:.3f}; T={T:.12f}; old={old:.9f}; new={new:.9f}; "
          f"delta={difference:.9f} nmol/mol; relative={relative * 100:.9f} %")
    assert isclose(old, target, rel_tol=1e-12)
    assert isclose(new / old, alpha_old / alpha_new, rel_tol=1e-12)

# B: signed error and additive correction for the first simulated point.
b_error = b_results[0][1] - b_results[0][0]
b_correction = -b_error
print(f"B point 1: intermediate={concentrations_target[0] / 1e9:.9g} atm; "
      f"converted={b_results[0][0]:.3f} nmol/mol; error={b_error:+.9f} nmol/mol; "
      f"correction={b_correction:+.9f} nmol/mol")
assert isclose(b_error, 1.2911068, abs_tol=1e-7)
assert isclose(b_correction, -1.2911068, abs_tol=1e-7)

# I: apply the declared coefficient pair to the simulated reference output.
scale_ratio = alpha_old / alpha_new
reference_output = 400.0
scaled_output = reference_output * scale_ratio
scaled_error = scaled_output - reference_output
relative_error_percent = 100 * scaled_error / reference_output
print(f"I applied: ratio={scale_ratio:.12f}; y={scaled_output:.9f} nmol/mol; "
      f"e={scaled_error:+.9f} nmol/mol; relative={relative_error_percent:+.9f} %")
assert isclose(scaled_output, 405.164427, abs_tol=1e-6)
assert isclose(scaled_error, 5.164427, abs_tol=1e-6)
assert isclose(relative_error_percent, 1.2911068, abs_tol=1e-7)

# Published coefficient-to-cross-section factors, in their declared order.
implicit_1 = 308.32 / 1.147
implicit_2 = 304.39 / 1.1329
implicit_difference_percent = 100 * (implicit_1 / implicit_2 - 1)
print(f"I implicit alpha/sigma: {implicit_1:.6f}; {implicit_2:.6f}; "
      f"relative difference={implicit_difference_percent:+.6f} %")
assert isclose(implicit_difference_percent, 0.045941, abs_tol=1e-6)

# Conversion check for the first simulated B concentration.
intermediate_atm = -log(transmittances[0]) / (alpha_old * path_cm)
converted_nmol_mol = intermediate_atm / standard_pressure_atm * 1e9
assert isclose(converted_nmol_mol, concentrations_target[0], abs_tol=1e-10)

# I: the two prescribed implementation pairs; no instrument correction inferred.
scale_pairs = ((1.147, 1.1329), (308.32, 304.39))
for numerator, denominator in scale_pairs:
    ratio = numerator / denominator
    print(f"I pair={numerator:.4f}/{denominator:.4f}; ratio={ratio:.12f}; "
          f"relative increment={(ratio - 1) * 100:.9f} %")

# A: simulated common and instrument-specific contributions in nmol/mol.
# Each output uses the same sensitivity (1) to shared S: it cancels in delta.
shared = 2.0
specific_1 = 0.3
specific_2 = -0.1
absolute_1 = shared + specific_1
absolute_2 = shared + specific_2
delta = absolute_1 - absolute_2
print(f"A shared S={shared:.3f}; Y1={absolute_1:.3f}; Y2={absolute_2:.3f}; "
      f"delta={delta:.3f} nmol/mol; residual specific={specific_1-specific_2:.3f} nmol/mol")
assert isclose(delta, specific_1 - specific_2, abs_tol=1e-12)
# A partial-cancellation check: unequal sensitivities 1 and 0.8.
partial_delta = (shared + specific_1) - (0.8 * shared + specific_2)
print(f"A unequal sensitivities: Y1={absolute_1:.3f}; "
      f"Y2={0.8 * shared + specific_2:.3f}; delta={partial_delta:.3f} nmol/mol")
assert isclose(partial_delta, 0.8, abs_tol=1e-12)
